css:
:root {
  /* Desert Sunset Theme - warm dunes and mirage light */
  --bg-primary: #fff7ed;
  --bg-alt: #ffe8cf;
  --bg-hover: #ffd7ad;
  --text-primary: #2c1b14;
  --text-secondary: #6b3f2c;
  --border: #e6a35c;
  --accent: #ff7f4d;
  --accent-rgb: 255, 127, 77;
  --accent-hover: #ff996d;
  --accent-hover-rgb: 255, 153, 109;
  --sun: #ffb347;
}

[data-theme="dark"] {
  --bg-primary: #1b0f0a;
  --bg-alt: #21130d;
  --bg-hover: #2b180f;
  --text-primary: #ffe8cf;
  --text-secondary: #f6c08f;
  --border: #c87037;
  --accent: #ff7f4d;
  --accent-rgb: 255, 127, 77;
  --accent-hover: #ffb347;
  --accent-hover-rgb: 255, 179, 71;
  --sun: #ff996d;
}

body {
  background: linear-gradient(180deg, #ffdfb5 0%, #ffb347 45%, #fe8c61 100%);
}

.card {
  background: linear-gradient(160deg, var(--bg-primary) 0%, var(--bg-alt) 100%);
  border: 1px solid var(--border);
  box-shadow: 0 14px 28px rgba(var(--accent-rgb), 0.2);
  position: relative;
  overflow: hidden;
}

.card::before {
  content: '';
  position: absolute;
  inset: -10%;
  background: radial-gradient(circle at 20% 20%, rgba(var(--accent-hover-rgb), 0.16), transparent 45%),
              radial-gradient(circle at 80% 60%, rgba(255, 255, 255, 0.12), transparent 40%);
  pointer-events: none;
}

.tag {
  background: rgba(var(--accent-rgb), 0.14);
  border: 1px solid var(--accent);
  color: var(--text-primary);
  border-radius: 999px;
}
